import { tv, type VariantProps } from "@/lib/beton/tv";

export const gridBackground = tv({
  slots: {
    root: "pointer-events-none absolute inset-0 -z-10",
  },
  variants: {
    weight: {
      light: { root: "opacity-40" },
      medium: { root: "opacity-70" },
      heavy: { root: "opacity-100" },
    },
  },
  defaultVariants: {
    weight: "medium",
  },
});

export const halftoneBackground = tv({
  slots: {
    root: "pointer-events-none absolute inset-0 -z-10",
  },
  variants: {
    weight: {
      light: { root: "opacity-15" },
      medium: { root: "opacity-30" },
      heavy: { root: "opacity-60" },
    },
  },
  defaultVariants: {
    weight: "medium",
  },
});

export const noiseOverlay = tv({
  slots: {
    root: "pointer-events-none absolute inset-0 z-10 mix-blend-multiply",
  },
  variants: {
    weight: {
      light: { root: "opacity-20" },
      medium: { root: "opacity-35" },
      heavy: { root: "opacity-60" },
    },
  },
  defaultVariants: {
    weight: "medium",
  },
});

export type GridBackgroundVariants = VariantProps<typeof gridBackground>;
export type HalftoneBackgroundVariants = VariantProps<typeof halftoneBackground>;
export type NoiseOverlayVariants = VariantProps<typeof noiseOverlay>;

import { noiseOverlay, type NoiseOverlayVariants } from "@/lib/beton/recipes/backgrounds.recipe";
import type { ComponentProps } from "react";

export interface NoiseOverlayProps
  extends Omit<ComponentProps<"div">, "children">, NoiseOverlayVariants {
  /** How fine the grain is. Higher is finer. */
  frequency?: number;
}

/**
 * Print grain over a section, drawn by the browser rather than loaded as an
 * image. Decorative, and hidden from screen readers.
 */
export function NoiseOverlay({
  weight = "medium",
  frequency = 0.8,
  className,
  ...props
}: NoiseOverlayProps) {
  const styles = noiseOverlay({ weight });
  const id = `beton-noise-${String(frequency).replace(".", "-")}`;
  return (
    <div {...props} aria-hidden="true" className={styles.root({ class: className })}>
      <svg width="100%" height="100%">
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency={frequency} numOctaves={3} />
          {/* Grain, not confetti: drop the colour the turbulence generates. */}
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </div>
  );
}
